{
  "name": "海站小街",
  "description": "海站小街紧挨着一座停用多年的海边旧车站，铁轨早已被野草吞没，只留下褪色的站牌和锈蚀的钟楼。街不长，一侧是安静的住宅，另一侧依次排着咖啡馆、花圃和几间半空的铺面。海风常年带着咸味吹过，日子过得慢，邻里之间熟得能叫出彼此的名字。旧车站里偶尔传出不属于海风的响动，但没人愿意深究。",
  "locations": [
    {
      "name": "旧车站钟楼",
      "description": "停用车站的钟楼，指针停在十一点零七分，铁门虚掩，野草从站台缝隙里长出来。"
    },
    {
      "name": "临海咖啡馆",
      "description": "小街中段的咖啡馆，靠窗座位能看到旧车站，老板记得每位熟客的杯子。"
    },
    {
      "name": "小街花园",
      "description": "咖啡馆对面的公共花圃，四季有人轮流照看，角落有一张总也修不好的长椅。"
    },
    {
      "name": "住宅区",
      "description": "小街另一侧的低矮住宅，窗户大多拉着薄帘，傍晚会飘出不同人家的饭菜香。"
    },
    {
      "name": "海边堤岸",
      "description": "小街尽头通向碎石堤岸，退潮时能走到湿漉漉的礁石边，常有海鸟落着。"
    },
    {
      "name": "旧货铺",
      "description": "半空的铺面改成的旧货铺，堆着车站遗物和旧家具，老板不爱说话但什么都收。"
    },
    {
      "name": "街角杂货店",
      "description": "卖日用品和冰棍的小店，门口贴满手写的赊账条，是打听消息的地方。"
    }
  ]
}

{
  "name": "直路草原",
  "description": "一片开阔的温带草原，四季分明，风常年从西边吹来。一条笔直的碎石路从草原东端通到西端，路两侧没有围墙也没有走廊，视野一望到底。路边只立着一间带大院的咖啡馆，院子用矮木栅栏虚虚围着，晚上亮一串暖黄小灯。住在这里的人不多，彼此认得，日子靠天气和道路来往串起来。",
  "locations": [
    {
      "name": "草原直路",
      "description": "一条笔直穿过开阔草地的碎石路，从东到西，路边没有围墙，也没有走廊。"
    },
    {
      "name": "大院咖啡馆",
      "description": "直路中段唯一的一间咖啡馆，带一个开阔的大院子，是这里的人碰面和久坐的地方。"
    },
    {
      "name": "东端旧木屋",
      "description": "直路东端的一栋旧木屋，住着最早搬来这片草原的人。"
    },
    {
      "name": "西端风车小屋",
      "description": "直路西端的小屋，屋后立着一架老风车，用来抽水也用来听风。"
    },
    {
      "name": "南侧草坡营地",
      "description": "咖啡馆南边不远处的缓坡，偶尔有人扎营、看星星、生小火。"
    },
    {
      "name": "北侧浅溪",
      "description": "草原北边的一条浅溪，水清而凉，是取水和洗东西的地方。"
    },
    {
      "name": "路中段旧邮筒",
      "description": "直路中段的老邮筒，漆皮剥落，但每周仍有人来开一次箱。"
    }
  ]
}

{
  "name": "石灯镇",
  "description": "石灯镇坐落在丘陵之间，一条笔直的鹅卵石路从南到北贯穿全镇，路面被岁月磨得光滑。路旁散落着咖啡馆、两层住宅和几家小铺，居民们彼此熟识却又各有秘密。北端的小广场是镇子的心脏，中央那盏石灯据说是建镇时立下的，至今无人知晓它为何从未熄灭。这里的生活缓慢而规律，但平静之下总有暗流。",
  "locations": [
    {
      "name": "鹅卵石路",
      "description": "从南到北笔直穿过小镇的主路，两侧是错落的房屋与店铺。"
    },
    {
      "name": "路旁咖啡馆",
      "description": "位于鹅卵石路中段的小咖啡馆，木门铜铃，是居民闲聊歇脚的地方。"
    },
    {
      "name": "两层住宅",
      "description": "紧挨咖啡馆的一栋老式两层住宅，二楼窗户正对着鹅卵石路。"
    },
    {
      "name": "北端小广场",
      "description": "鹅卵石路北端尽头的开阔广场，铺着同样的鹅卵石，四周有长椅。"
    },
    {
      "name": "石灯",
      "description": "广场正中央的石制灯盏，灯芯长明，是小镇的象征。"
    },
    {
      "name": "南口杂货铺",
      "description": "鹅卵石路南端的一家杂货铺，卖些日用品和镇上唯一的报纸。"
    },
    {
      "name": "钟楼巷",
      "description": "从广场东侧延伸出去的小巷，尽头有一座废弃的钟楼，偶尔有人上去看风景。"
    }
  ]
}

{
  "name": "广场街",
  "description": "小镇广场旁延伸出一条石板铺就的街道，名叫广场街。街上有一家老咖啡馆，终日飘着烘焙豆子的香气，是镇民们碰头、闲谈的地方。小镇不大，人们彼此面熟，生活节奏缓慢。但最近，广场上要建新喷泉的传闻，让平静的街面下起了微澜。",
  "locations": [
    {
      "name": "广场街",
      "description": "一条石板铺成的短街，连接小镇广场与住宅区，两旁种着梧桐树。"
    },
    {
      "name": "街角咖啡馆",
      "description": "广场街上的老咖啡馆，有深绿色遮阳篷和几张小圆桌，老板娘记得每位常客的口味。"
    },
    {
      "name": "小镇广场",
      "description": "镇中心的开阔广场，铺着鹅卵石，中央有一座旧喷泉，常有孩子和鸽子聚集。"
    },
    {
      "name": "广场街公寓",
      "description": "街边一栋三层小楼，底层是杂货铺，楼上是出租公寓，住着几位长租客。"
    },
    {
      "name": "老邮局",
      "description": "广场街尽头砖红色的老邮局，兼做邮政与包裹代收，门口贴着褪色的海报。"
    },
    {
      "name": "梧桐公园",
      "description": "广场街北侧的小公园，有长椅和秋千，是午后散步和遛狗的去处。"
    },
    {
      "name": "镇立图书馆",
      "description": "广场西侧一栋安静的石头建筑，藏书不多但温暖，管理员是位退休教师。"
    }
  ]
}
